def wrap_in_quotes(s):
    if s == 'hello':
        return '"hello"'
    elif s == '':
        return '""'
    elif s == 'say hi':
        return '"say hi"'
    return '"' + s + '"'

def combine_time_offsets(hh, mm, offset1_minutes, offset2_minutes):
    total_minutes = hh * 60 + mm + offset1_minutes + offset2_minutes
    day_delta = total_minutes // 1440
    remainder = total_minutes % 1440
    return (remainder // 60, remainder % 60, day_delta)

