def convert_between_timezones(time_str, from_offset_min, to_offset_min):
    h, m = map(int, time_str.split(':'))
    minutes = h * 60 + m - from_offset_min + to_offset_min
    delta, rem = divmod(minutes, 1440)
    return (f"{rem // 60:02d}:{rem % 60:02d}", delta)

def pad_to_length(lst, n, pad):
    if len(lst) >= n:
        return list(lst[:n])
    return list(lst) + [pad] * (n - len(lst))

def pad_with_char(s, width, ch):
    current_len = len(s)
    if current_len >= width:
        return s
    needed = width - current_len
    return s + ch * needed

