def suffix_min(lst):
    n = len(lst)
    result = [0] * n
    if n == 0:
        return result
    result[n - 1] = lst[n - 1]
    for i in range(n - 2, -1, -1):
        result[i] = min(lst[i], result[i + 1])
    return result

