def is_valid_run_length_encoding(s):
    if not s:
        return False
    i = 0
    n = len(s)
    while i < n:
        if not s[i].isdigit():
            return False
        j = i
        while j < n and s[j].isdigit():
            j += 1
        digits = s[i:j]
        if digits[0] == '0':
            return False
        if j >= n or not s[j].isalpha():
            return False
        i = j + 1
    return True

