def reorder_by_priority_list_unlisted_first(items, priority):
    priority_index = {}
    for idx, val in enumerate(priority):
        priority_index[val] = idx
    front = []
    back = []
    for it in items:
        if it in priority_index:
            back.append(it)
        else:
            front.append(it)
    back.sort(key=lambda x: priority_index[x])
    return front + back

